using UnityEngine;
using UnityEditor;
using System;
using System.IO;
using System.Linq;
using System.Text;
using ConRoi.Investigation.V36;

namespace Unity.AI.Assistant.Agent.Dynamic.Extension.Editor
{
    internal class CommandScript : IRunCommand
    {
        public void Execute(ExecutionResult r)
        {
            if (!EditorApplication.isPlaying)
                throw new Exception("Play required");
            var s = UnityEngine.Object.FindFirstObjectByType<InvestigationSession>();
            s.SaveDirectoryOverride = Path.GetFullPath("Test/KetQua/investigation_r102/lifecycle-profile");
            var log = new StringBuilder("API-level bounded lifecycle/content checks; not mouse UI or controller traversal evidence.\n");
            Action<bool, string> check = (ok, msg) =>
            {
                log.AppendLine((ok ? "PASS " : "FAIL ") + msg);
                File.WriteAllText("Test/KetQua/investigation_r102/lifecycle-api.txt", log.ToString());
                if (!ok)
                    throw new Exception(msg);
            };
            s.ClosePage();
            s.SetPaused(true);
            check(Time.timeScale == 0 && !s.movement.enabled && !s.look.enabled, "pause disables unchanged movement/look and time");
            s.SetPaused(false);
            check(Time.timeScale == 1 && s.movement.enabled && s.look.enabled, "resume");
            var pos = s.movement.transform.position;
            int count = s.GetComponentsInChildren<InvestigationInteractable>(true).Length;
            s.Acquire("shoeprint");
            s.Acquire("fabric");
            s.Observe("shoeprint", 0);
            s.Observe("fabric", 0);
            check(!s.data.finalized && s.data.conclusions.All(c => c.choice == 0), "shoe/fabric never auto finalize or identify timing/intent");
            s.Acquire("letter");
            s.data.mapping.Clear();
            s.RecordReading();
            check(!s.Has("decoded"), "empty map no automatic solution");
            s.Assign("T", "Z");
            check(s.ReadCipher().Contains("Z"), "arbitrary wrong mapping allowed");
            s.Assign("T", "");
            check(!s.ReadCipher().Contains("Z"), "clear mapping");
            foreach (char c in InvestigationContent.Alphabet)
                s.Assign(c.ToString(), c.ToString());
            s.RecordReading();
            check(s.Has("decoded") && !s.data.finalized, "partial cipher lead no sender conclusion");
            s.AddRelation("fabric", "shoeprint", "Test: these do not establish event timing.");
            check(s.data.relations.Count > 0, "free relation stored without correctness grading");
            s.Acquire("clip");
            s.data.clipBeforeSeen = false;
            s.data.clipEventSeen = false;
            s.Observe("clip", 0);
            check(!s.Observation("clip", 0), "unwatched clip observations locked");
            foreach (string page in new[]{"cipher", "compare", "reconstruction", "conclusions"})
            {
                s.OpenPage(page);
                s.Save();
                string before = JsonUtility.ToJson(s.data);
                for (int i = 0; i < 3; i++)
                    check(s.Load(), "load " + page + " " + i);
                check(Vector3.Distance(pos, s.movement.transform.position) < .00001f, "no cumulative movement " + page);
                check(s.Page == page, "restored page " + page);
                check(s.data.mapping.Count == InvestigationContent.Alphabet.Length && s.data.relations.Count > 0, "records survive " + page);
            }

            s.Acquire("r03");
            s.OpenEvidence("r03");
            s.Save();
            check(s.Load() && s.Page == "inspect" && s.data.inspecting == "r03", "inspection restored");
            s.ClosePage();
            s.OpenPage("reconstruction");
            s.StartTrial("wedge");
            s.Save();
            check(s.Load() && !s.TrialRunning && s.modelGate.state.latched, "active trial safely reset on load");
            s.ClosePage();
            s.gate.state.angle = 35;
            s.gate.state.latched = false;
            s.gate.state.wedge = true;
            s.Save();
            s.gate.ResetGate();
            check(s.Load() && Mathf.Abs(s.gate.state.angle - 35) < .001f && s.gate.state.wedge, "physical gate saved/restored");
            s.gate.ResetGate();
            s.Save();
            string valid = File.ReadAllText(s.SavePath);
            File.WriteAllText(s.SavePath, valid.Replace("conroi.investigation.v36.r102", "old.gameplay"));
            check(!s.Load(), "reject old namespace without migration");
            File.WriteAllText(s.SavePath, valid);
            check(s.Load(), "restore own valid test file");
            s.ClosePage();
            check(s.GetComponentsInChildren<InvestigationInteractable>(true).Length == count, "no interactable duplication");
            r.Log(log.ToString());
        }
    }
}

